32	    /**
33	     * Study a professional asset to learn its production norms.
34	     */
35	    public async study(modelId: string): Promise<Result<PedagogyProfile>> {
36	        logger.info({ modelId }, 'Starting production pedagogy study');
37	
38	        try {
39	            // 1. Semantic Enrichment (Wiki)
40	            // Extract a name hint from the ID if possible (e.g., npc:0 -> Hans mapping)
41	            // In a real scenario, this would use a Cache-to-Lore mapping table.
42	            const nameHint = modelId === 'npc:0' ? 'Hans' : (modelId.startsWith('npc:') ? 'NPC' : 'unknown');
43	            const wikiResult = await WikiEnricher.enrich(nameHint);
44	
45	            // 2. Headless Rendering & Analysis
46	            const cachePath = getrsmvCachePath();
47	            const pedagogyProfilePath = join(process.cwd(), 'pedagogy_profile.json');
48	            const wikiContextPath = join(process.cwd(), 'wiki_context.json');
49	
50	            // Write wiki context to file to avoid shell escaping issues
51	            if (wikiResult.ok) {
52	                await fs.writeFile(wikiContextPath, JSON.stringify(wikiResult.value));
53	            }
54	
55	            // Spawn headless CLI with --analyze and --wiki (as file path)
56	            const npxCmd = process.platform === 'win32' ? 'npx.cmd' : 'npx';
57	            const subprocess = spawn(npxCmd, [
58	                'tsx', join(getrsmvSubstratePath(), 'src', 'headless', 'cli.ts'),
59	                '--model', modelId,
60	                '--source', `cache:${cachePath}`,
61	                '--analyze',
62	                ...(wikiResult.ok ? ['--wiki', 'wiki_context.json'] : [])
63	            ], {
64	                shell: true,
65	                env: { ...process.env, POG_rsmv_CACHE_DIR: cachePath }
66	            });
67	
68	            let output = '';
69	            subprocess.stdout?.on('data', d => output += d);
70	            subprocess.stderr?.on('data', d => output += d);
71	
72	            await new Promise((resolve, reject) => {
73	                subprocess.on('exit', (code) => {
74	                    if (code === 0) resolve(true);
75	                    else {
76	                        logger.error({ code, output }, 'Headless analysis subprocess failed');
77	                        reject(new Error(`Headless analysis failed with code ${code}`));
78	                    }
79	                });
80	            });
81	
82	            // 3. Ingest Distilled Wisdom
83	            const profileData = await fs.readFile(pedagogyProfilePath, 'utf8');
84	            const profile = JSON.parse(profileData) as PedagogyProfile;
85	
86	            // 4. Final Semantic Fusion (Fusion Layer)
87	            if (wikiResult.ok) {
88	                const lore = wikiResult.value;
89	                (profile.semantics as any).loreExtract = lore.intent;
90	                (profile.semantics as any).wikiVariables = lore.variables;
91	                if (lore.race) (profile.semantics as any).race = lore.race;
92	
93	                // Extract combat level from variables if present
94	                if (lore.variables?.combat) {
95	                    (profile.metrics as any).combatLevel = parseInt(lore.variables.combat);
96	                }
97	            }
98	
99	            // 5. Cleanup (The Purge)
100	            await this.cleanup();
101	
102	            logger.info({ modelId, polyCount: profile.metrics.polyCount, combatLevel: (profile.metrics as any).combatLevel }, 'Pedagogy study complete');
103	            return { ok: true, value: profile };
104	
105	        } catch (err) {
106	            logger.error({ err, modelId }, 'Pedagogy study failed');
107	            return { ok: false, error: err as Error };
108	        }
109	    }
