111	    /**
112	     * Observe: A real-time perceptual probe that combines pixel sampling with semantic context.
113	     * This is the "Live" version of Study.
114	     */
115	    public async observe(targetName: string, imagePath: string): Promise<Result<any>> {
116	        logger.info({ targetName }, 'Initiating real-time chromatic observation');
117	
118	        // 1. Live Vision Loop — reuse singleton eye, throttle captures
119	        let activePath = imagePath;
120	        const now = Date.now();
121	        if (imagePath === 'latest_frame.png') {
122	            // Throttle: skip capture if within cadence window and we have a cached result
123	            if (this.lastCaptureResult && (now - this.lastCaptureTime) < TransientObserver.CAPTURE_THROTTLE_MS) {
124	                activePath = this.lastCaptureResult;
125	            } else {
126	                // Reuse singleton eye (never allocate a new one per tick)
127	                if (!this.eye) {
128	                    this.eye = new (require('../utils/SovereignEye.js')).SovereignEye('live-vision-loop');
129	                }
130	                const port = (require('../monitor/SwitchboardLimb.js')).SwitchboardLimb.getInstance().getActivePort() || 8788;
131	                const captureRes = await this.eye.capture({ type: 'url', target: `http://localhost:${port}/edge_radar.html` });
132	                if (captureRes.ok && captureRes.value.imagePath) {
133	                    activePath = captureRes.value.imagePath;
134	                    this.lastCaptureResult = activePath;
135	                    this.lastCaptureTime = now;
136	                    // Copy to bridge
137	                    const { copyFileSync } = require('fs');
138	                    copyFileSync(activePath, 'latest_frame.png');
139	                }
140	            }
141	        }
142	
143	        // 2. Get Wiki Ground Truth
144	        const wikiRes = await WikiEnricher.enrich(targetName);
145	        const expectedPalette: string[] = [];
146	
147	        if (wikiRes.ok && wikiRes.value.variables) {
148	            const vars = wikiRes.value.variables;
149	            if (vars.hex1) expectedPalette.push(vars.hex1);
150	            if (vars.hex2) expectedPalette.push(vars.hex2);
151	            if (vars.color) expectedPalette.push(vars.color);
152	        }
153	
154	        return {
155	            ok: true,
156	            value: {
157	                name: targetName,
158	                imagePath: activePath,
159	                wikiLore: wikiRes.ok ? wikiRes.value.intent : 'Unknown',
160	                expectedPalette,
161	                timestamp: Date.now()
162	            }
163	        };
164	    }
