54	/**
55	 * SpatialVisionEngine Ã¢â‚¬â€ Enhanced vision with spatial mapping for Kimi
56	 * Provides line/color/space key maps so Kimi knows exactly what's on screen
57	 */
58	export class SpatialVisionEngine {
59	    private static instance: SpatialVisionEngine | undefined;
60	    private readonly client: ModelClient;
61	    private readonly shell: ShellEngine;
