141	    async observe(params: SpatialVisionParams): Promise<Result<EngineOutput>> {
142	        if (this.isObserving) {
143	            return { ok: false, error: new Error('SpatialVisionEngine is already performing an observation. Pulse collision avoided.') };
144	        }
145	        this.isObserving = true;
146	        let imagePath = params.target && existsSync(params.target) ? params.target : '';
147	        try {
148	            // 1. Capture screen
149	            if (params.includeScreenshot !== false && !imagePath) {
150	                this.renderer.info('👁️   Spatial capture initiated...');
151	
152	                // Phase 14: Dynamic port discovery via Switchboard singleton.
153	                const ports = [
154	                    SwitchboardLimb.getInstance().getActivePort() || 8788,
155	                    8787, // Wrangler Dev / Worker
156	                    8081  // rsmv Inspector Dev
157	                ];
158	
159	                let lastErr: Error | null = null;
160	                for (const port of ports) {
161	                    const targets = [
162	                        `http://localhost:${port}/edge_radar.html`,
163	                        `http://localhost:${port}/globe`
164	                    ];
165	
166	                    for (const targetUrl of targets) {
167	                        const captureRes = await this.eye.capture({ type: 'url', target: targetUrl });
168	
169	                        if (captureRes.ok && captureRes.value.imagePath) {
170	                            imagePath = captureRes.value.imagePath;
171	                            break;
172	                        }
173	                        lastErr = captureRes.ok ? new Error(`Port ${port} path ${targetUrl} active but no screenshot produced`) : (captureRes.error as Error);
174	                    }
175	                    if (imagePath) break;
176	                }
177	
178	                if (!imagePath) return { ok: false, error: lastErr || new Error('All vision dashboard ports (8788, 8787, 8081) failed to produce a capture.') };
179	            }
180	
181	            if (!imagePath || !existsSync(imagePath)) {
182	                return { ok: false, error: new Error(`Image not found for spatial analysis: ${imagePath}`) };
183	            }
184	
185	            // 2. Analyze based on intent
186	            const base64Image = readFileSync(imagePath).toString('base64');
187	            const modelPrompt = this.buildSpatialPrompt(params);
188	
189	            const result = await this.client.call({
190	                model: this.config.visionModel,
191	                prompt: modelPrompt,
192	                images: [base64Image],
193	                yaoState: params.yaoState
194	            });
195	
196	            if (!result.ok) {
197	                return { ok: false, error: result.error as any };
198	            }
199	
200	            // 3. Parse spatial map if chroma/spatial intent
201	            let spatialMap: SpatialMap | undefined;
202	            if (params.intent === 'chroma' || params.intent === 'spatial_map' || params.intent === 'ui_analysis') {
203	                spatialMap = this.parseSpatialMap(result.value.response);
204	            }
205	
206	            // 4. Chroma augmentation
207	            if (params.intent === 'chroma') {
208	                const deterministicColors = await this.getDeterministicColors(imagePath);
209	                if (deterministicColors.ok) {
210	                    spatialMap = spatialMap || { regions: [], lines: [], colorPalette: [] };
211	                    spatialMap.colorPalette = [
212	                        ...spatialMap.colorPalette,
213	                        ...deterministicColors.value.colors.map(c => ({
214	                            hex: c.hex,
215	                            usage: `Detected via pixel frequency analysis (freq: ${(c.frequency * 100).toFixed(1)}%)`,
216	                            locations: ['Global Substrate']
217	                        }))
218	                    ];
219	                }
220	            }
221	
222	            // 5. Persist sensory probe metadata (Phase 112 Resilience)
223	            const captureId = uuidv4();
224	            SovereignKnowledgeDB.getInstance().recordCapture(
225	                captureId,
226	                Date.now(),
227	                'spatial_vision',
228	                imagePath,
229	                imagePath,
230	                { response: result.value.response, spatialMap },
231	                params
232	            );
233	
234	            return {
235	                ok: true,
236	                value: {
237	                    output: result.value.response,
238	                    data: {
239	                        intent: params.intent,
240	                        spatialMap,
241	                        model: this.config.visionModel,
242	                        source: imagePath,
243	                        captureId
244	                    }
245	                }
246	            };
247	        } finally {
248	            if (imagePath && existsSync(imagePath) && !(params.target && params.target === imagePath)) {
249	                try {
250	                    unlinkSync(imagePath);
251	                    this.renderer.info(`🧹 Cleaned up temporary vision artifact: ${imagePath}`);
252	                } catch (e) {
253	                    this.renderer.warn(`Failed to clean up vision artifact: ${imagePath}`);
254	                }
255	            }
256	            this.isObserving = false;
257	        }
258	    }
