356	    private parseSpatialMap(response: string): SpatialMap | undefined {
357	        try {
358	            // Try to extract JSON from response
359	            const jsonMatch = response.match(/\{[\s\S]*\}/);
360	            if (jsonMatch) {
361	                const parsed = JSON.parse(jsonMatch[0]);
362	                return {
363	                    regions: parsed.regions || [],
364	                    lines: parsed.lines || [],
365	                    colorPalette: parsed.colorPalette || []
366	                };
367	            }
368	        } catch {
369	            // JSON parsing failed, return undefined
370	        }
371	        return undefined;
372	    }
