374	    /**
375	     * Generate a text-based spatial map for Kimi to reference
376	     */
377	    generateTextMap(spatialMap: SpatialMap, width = 80, height = 24): string {
378	        const grid: string[][] = [];
379	
380	        // Initialize empty grid
381	        for (let y = 0; y < height; y++) {
382	            grid[y] = new Array(width).fill(' ');
383	        }
384	
385	        // Place regions
386	        for (const region of spatialMap.regions) {
387	            const rx = Math.floor((region.x / 1920) * width);
388	            const ry = Math.floor((region.y / 1080) * height);
389	            const rw = Math.max(1, Math.floor((region.width / 1920) * width));
390	            const rh = Math.max(1, Math.floor((region.height / 1080) * height));
391	
392	            const char = region.type.charAt(0).toUpperCase();
393	            for (let y = ry; y < Math.min(ry + rh, height); y++) {
394	                for (let x = rx; x < Math.min(rx + rw, width); x++) {
395	                    if (y >= 0 && y < height && x >= 0 && x < width) {
396	                        grid[y]![x] = char;
397	                    }
398	                }
399	            }
400	        }
401	
402	        // Draw lines
403	        for (const line of spatialMap.lines) {
404	            const sx = Math.floor((line.startX / 1920) * width);
405	            const sy = Math.floor((line.startY / 1080) * height);
406	            const ex = Math.floor((line.endX / 1920) * width);
407	            const ey = Math.floor((line.endY / 1080) * height);
408	
409	            // Simple line drawing
410	            if (sx === ex) { // Vertical
411	                for (let y = Math.min(sy, ey); y <= Math.max(sy, ey) && y < height; y++) {
412	                    if (y >= 0 && sx >= 0 && sx < width) grid[y]![sx] = '|';
413	                }
414	            } else if (sy === ey) { // Horizontal
415	                for (let x = Math.min(sx, ex); x <= Math.max(sx, ex) && x < width; x++) {
416	                    if (sy >= 0 && sy < height && x >= 0) grid[sy]![x] = '-';
417	                }
418	            }
419	        }
420	
421	        // Convert to string
422	        return grid.map(row => row.join('')).join('\n');
423	    }
