138	<script>
139	const canvas = document.getElementById('radar');
140	const ctx = canvas.getContext('2d');
141	const tooltip = document.getElementById('tooltip');
142	
143	let regionData = null;
144	let matrixMap = {};   // "x_y" -> { walkable, surfaceType, edges, sourceFlags }
145	let entities = [];
146	let ghostGaussians = []; // Received via WebSocket
147	let ghostHeatmap = null;
148	let ghostSafespots = []; // Received via WebSocket — zero-heat predicted safe tiles
149	let worldOriginX = 0, worldOriginY = 0;
150	let ws = null;
151	let trackPlayer = true;
152	let playerX = null;
153	let playerY = null;
154	
155	function toggleTracking() {
156	  trackPlayer = !trackPlayer;
157	  const btn = document.getElementById('trackBtn');
158	  if (trackPlayer) {
159	    btn.classList.add('tracking-active');
160	    btn.innerHTML = '⚡ Tracking Player: ON';
161	    if (playerX !== null && playerY !== null) {
162	      updateLocationFromPlayer();
163	    }
164	  } else {
165	    btn.classList.remove('tracking-active');
166	    btn.innerHTML = 'Track Player Location';
167	  }
168	}
169	
170	function updateLocationFromPlayer() {
171	  if (playerX === null || playerY === null) return;
172	  const rx = Math.floor(playerX / 64);
173	  const ry = Math.floor(playerY / 64);
174	  
175	  const currentRx = parseInt(document.getElementById('rx').value);
176	  const currentRy = parseInt(document.getElementById('ry').value);
177	  
178	  if (rx !== currentRx || ry !== currentRy || !regionData) {
179	    document.getElementById('rx').value = rx;
180	    document.getElementById('ry').value = ry;
181	    loadRegion();
182	  }
183	}
184	
185	function connectWS() {
186	  const wsUrl = `ws://${window.location.hostname}:${window.location.port}`;
187	  ws = new WebSocket(wsUrl);
188	  ws.onmessage = (e) => {
189	    const data = JSON.parse(e.data);
190	    if (data.type === 'ghost_splat') {
191	      ghostGaussians = data.payload.gaussians || [];
192	      ghostHeatmap = data.payload.heatmap || null;
193	      ghostSafespots = data.payload.safespots || [];
194	      if (document.getElementById('showGhosts').checked || document.getElementById('showHeatmap').checked) redraw();
195	    } else if (data.type === 'GAME_STATE') {
196	      const avatar = data.payload.avatar;
197	      if (avatar) {
198	        playerX = avatar.x;
199	        playerY = avatar.y;
200	        if (trackPlayer) {
201	          updateLocationFromPlayer();
202	        }
203	      }
204	    }
205	  };
206	  ws.onclose = () => setTimeout(connectWS, 2000);
207	  ws.onerror = () => ws.close();
208	}
209	connectWS();
210	
211	function surfaceColor(tile) {
212	  if (!tile) return [8, 8, 14];
213	  if (!tile.walkable) return [220, 50, 47];
214	  switch (tile.surfaceType) {
215	    case 'water':   return [26, 74, 107];
216	    case 'bridge':  return [107, 74, 26];
217	    default:        return [15, 26, 18];
218	  }
219	}
220	
221	function redraw() {
222	  if (!regionData) return;
223	  const scale = parseInt(document.getElementById('scale').value);
224	  const showEdges = document.getElementById('showEdges').checked;
225	  const showEntities = document.getElementById('showEntities').checked;
226	  const size = 64;
227	
228	  canvas.width = size * scale;
229	  canvas.height = size * scale;
230	
231	  // Pass 1: Tile fill
232	  const imgData = ctx.createImageData(canvas.width, canvas.height);
233	  for (let lx = 0; lx < size; lx++) {
234	    for (let ly = 0; ly < size; ly++) {
235	      const wx = worldOriginX + lx;
236	      const wy = worldOriginY + ly;
237	      const key = `${wx}_${wy}`;
238	      const tile = matrixMap[key];
239	      const color = surfaceColor(tile);
240	
241	      for (let dx = 0; dx < scale; dx++) {
242	        for (let dy = 0; dy < scale; dy++) {
243	          const px = lx * scale + dx;
244	          const py = (size - 1 - ly) * scale + dy;
245	          const idx = (py * canvas.width + px) * 4;
246	          imgData.data[idx]     = color[0];
247	          imgData.data[idx + 1] = color[1];
248	          imgData.data[idx + 2] = color[2];
249	          imgData.data[idx + 3] = 255;
250	        }
251	      }
252	    }
253	  }
254	  ctx.putImageData(imgData, 0, 0);
255	
256	  // Pass 2: Edge overlay (drawn as lines on tile boundaries)
257	  if (showEdges) {
258	    ctx.lineWidth = Math.max(1, scale / 6);
259	    
260	    for (let lx = 0; lx < size; lx++) {
261	      for (let ly = 0; ly < size; ly++) {
262	        const wx = worldOriginX + lx;
263	        const wy = worldOriginY + ly;
264	        const key = `${wx}_${wy}`;
265	        const tile = matrixMap[key];
266	        if (!tile || !tile.edges) continue;
267	
268	        const canvasX = lx * scale;
269	        const canvasY = (size - 1 - ly) * scale;
270	
271	        // North edge = top of the tile cell (canvasY)
272	        if (tile.edges.northBlocked) {
273	          ctx.strokeStyle = '#ff3030';
274	          ctx.beginPath();
275	          ctx.moveTo(canvasX, canvasY);
276	          ctx.lineTo(canvasX + scale, canvasY);
277	          ctx.stroke();
278	        }
279	        // South edge = bottom of the tile cell (canvasY + scale)
280	        if (tile.edges.southBlocked) {
281	          ctx.strokeStyle = '#ff3030';
282	          ctx.beginPath();
283	          ctx.moveTo(canvasX, canvasY + scale);
284	          ctx.lineTo(canvasX + scale, canvasY + scale);
285	          ctx.stroke();
286	        }
287	        // East edge = right side (canvasX + scale)
288	        if (tile.edges.eastBlocked) {
289	          ctx.strokeStyle = '#ff3030';
290	          ctx.beginPath();
291	          ctx.moveTo(canvasX + scale, canvasY);
292	          ctx.lineTo(canvasX + scale, canvasY + scale);
293	          ctx.stroke();
294	        }
295	        // West edge = left side (canvasX)
296	        if (tile.edges.westBlocked) {
297	          ctx.strokeStyle = '#ff3030';
298	          ctx.beginPath();
299	          ctx.moveTo(canvasX, canvasY);
300	          ctx.lineTo(canvasX, canvasY + scale);
301	          ctx.stroke();
302	        }
303	      }
304	    }
305	  }
306	
307	  // Pass 3: Entity markers
308	  if (showEntities && entities.length > 0) {
309	    for (const ent of entities) {
310	      const lx = ent.x - worldOriginX;
311	      const ly = ent.y - worldOriginY;
312	      if (lx < 0 || lx >= size || ly < 0 || ly >= size) continue;
313	
314	      const px = lx * scale + scale / 2;
315	      const py = (size - 1 - ly) * scale + scale / 2;
316	
317	      const isNpc = ent.type === 'npc';
318	      ctx.beginPath();
319	      ctx.arc(px, py, scale / 3, 0, Math.PI * 2);
320	      ctx.fillStyle = isNpc ? 'rgba(81, 255, 255, 0.7)' : 'rgba(180, 120, 255, 0.6)';
321	      ctx.fill();
322	
323	      if (scale >= 12 && ent.name) {
324	        ctx.fillStyle = '#fff';
325	        ctx.font = `bold ${Math.min(9, scale / 1.4)}px Segoe UI`;
326	        ctx.textAlign = 'center';
327	        ctx.fillText(ent.name, px, py - scale / 2.2);
328	      }
329	    }
330	  }
331	  
332	  // Pass 3.1: Player pulsing marker
333	  if (playerX !== null && playerY !== null) {
334	    const lx = playerX - worldOriginX;
335	    const ly = playerY - worldOriginY;
336	    if (lx >= 0 && lx < size && ly >= 0 && ly < size) {
337	      const px = lx * scale + scale / 2;
338	      const py = (size - 1 - ly) * scale + scale / 2;
339	
340	      // Pulsing glow circle
341	      const pulse = (Date.now() % 1000) / 1000;
342	      ctx.beginPath();
343	      ctx.arc(px, py, scale / 2 + pulse * scale / 4, 0, Math.PI * 2);
344	      ctx.strokeStyle = 'rgba(81, 255, 120, 0.4)';
345	      ctx.lineWidth = 2;
346	      ctx.stroke();
347	
348	      // Main player circle
349	      ctx.beginPath();
350	      ctx.arc(px, py, scale / 3, 0, Math.PI * 2);
351	      ctx.fillStyle = '#51ff78'; // Bright green for player
352	      ctx.fill();
353	      ctx.strokeStyle = '#ffffff';
354	      ctx.lineWidth = 1.5;
355	      ctx.stroke();
356	      
357	      // Label "Sovereign"
358	      ctx.fillStyle = '#51ff78';
359	      ctx.font = `bold ${Math.min(10, scale / 1.2)}px Segoe UI`;
360	      ctx.textAlign = 'center';
361	      ctx.fillText('Sovereign', px, py - scale / 2.2);
362	    }
363	  }
364	  
365	  // Pass 3.5: Thermal Heatmap Overlay (yellow → orange → red → white gradient)
366	  if (document.getElementById('showHeatmap').checked && ghostHeatmap && ghostHeatmap.length > 0) {
367	    const PADDED_SIZE = 66;
368	    // Find max intensity for normalisation
369	    let maxHeat = 1;
370	    for (let i = 0; i < ghostHeatmap.length; i++) {
371	      if (ghostHeatmap[i] > maxHeat) maxHeat = ghostHeatmap[i];
372	    }
373	
374	    for (let ly = 0; ly < PADDED_SIZE; ly++) {
375	      for (let lx = 0; lx < PADDED_SIZE; lx++) {
376	        const raw = ghostHeatmap[ly * PADDED_SIZE + lx];
377	        if (raw === 0) continue;
378	
379	        // Translate from padded (66x66) to 64x64 view (offset by 1)
380	        const tx = lx - 1;
381	        const ty = ly - 1;
382	        if (tx < 0 || tx >= size || ty < 0 || ty >= size) continue;
383	
384	        const px = tx * scale;
385	        const py = (size - 1 - ty) * scale;
386	
387	        // Normalised 0‥1, clamped
388	        const t = Math.min(raw / maxHeat, 1.0);
389	
390	        // 5-stop gradient: dark-red → red → orange → yellow → white
391	        let r, g, b, a;
392	        if (t < 0.25) {
393	          // dark-red → red
394	          const s = t / 0.25;
395	          r = Math.round(120 + 135 * s); g = 0; b = 0; a = 0.25 + 0.2 * s;
396	        } else if (t < 0.5) {
397	          // red → orange
398	          const s = (t - 0.25) / 0.25;
399	          r = 255; g = Math.round(100 * s); b = 0; a = 0.45 + 0.1 * s;
400	        } else if (t < 0.75) {
401	          // orange → yellow
402	          const s = (t - 0.5) / 0.25;
403	          r = 255; g = Math.round(100 + 155 * s); b = 0; a = 0.55 + 0.1 * s;
404	        } else {
405	          // yellow → white
406	          const s = (t - 0.75) / 0.25;
407	          r = 255; g = 255; b = Math.round(255 * s); a = 0.65 + 0.2 * s;
408	        }
409	
410	        ctx.fillStyle = `rgba(${r},${g},${b},${a.toFixed(2)})`;
411	        ctx.fillRect(px, py, scale, scale);
412	      }
413	    }
414	  }
415	
416	  // Pass 3.6: Safespot Crosses (cyan '+' markers on zero-heat tiles)
417	  if (document.getElementById('showGhosts').checked && Array.isArray(ghostSafespots) && ghostSafespots.length > 0) {
418	    ctx.strokeStyle = 'rgba(0, 255, 200, 0.85)';
419	    ctx.lineWidth = Math.max(1, scale / 8);
420	    const arm = scale * 0.35;
421	    for (const sp of ghostSafespots) {
422	      const lx = sp.x - worldOriginX;
423	      const ly = sp.y - worldOriginY;
424	      if (lx < 0 || lx >= size || ly < 0 || ly >= size) continue;
425	      const cx2 = lx * scale + scale / 2;
426	      const cy2 = (size - 1 - ly) * scale + scale / 2;
427	      // Glow shadow
428	      ctx.shadowColor = '#00ffc8';
429	      ctx.shadowBlur = 4;
430	      ctx.beginPath();
431	      ctx.moveTo(cx2 - arm, cy2); ctx.lineTo(cx2 + arm, cy2);
432	      ctx.moveTo(cx2, cy2 - arm); ctx.lineTo(cx2, cy2 + arm);
433	      ctx.stroke();
434	      ctx.shadowBlur = 0;
435	    }
436	  }
437	
438	
439	  // Pass 4: Ghost Splats (Gaussian Predictions)
440	  if (document.getElementById('showGhosts').checked && ghostGaussians.length > 0) {
441	    const PADDED_SIZE = 66;
442	    for (let i = 0; i < ghostGaussians.length; i += 13) {
443	      const lx_rel = ghostGaussians[i + 0];
444	      const lz_rel = ghostGaussians[i + 1]; 
445	      const ly_rel = ghostGaussians[i + 2];
446	      
447	      const s11 = ghostGaussians[i + 3];
448	      const s33 = ghostGaussians[i + 8];
449	      
450	      const r = ghostGaussians[i + 9] * 255;
451	      const g = ghostGaussians[i + 10] * 255;
452	      const b = ghostGaussians[i + 11] * 255;
453	      const a = ghostGaussians[i + 12];
454	
455	      const lx = lx_rel + (PADDED_SIZE / 2) - 1;
456	      const ly = ly_rel + (PADDED_SIZE / 2) - 1;
457	
458	      if (lx < 0 || lx >= size || ly < 0 || ly >= size) continue;
459	
460	      const px = lx * scale + scale / 2;
461	      const py = (size - 1 - ly) * scale + scale / 2;
462	
463	      const radiusX = Math.sqrt(s11) * scale * 2;
464	      const radiusY = Math.sqrt(s33) * scale * 2;
465	
466	      const maxR = Math.max(radiusX, radiusY, 1);
467	      const gradient = ctx.createRadialGradient(px, py, 0, px, py, maxR);
468	      gradient.addColorStop(0, `rgba(${Math.round(r)},${Math.round(g)},${Math.round(b)},${a * 0.6})`);
469	      gradient.addColorStop(1, `rgba(${Math.round(r)},${Math.round(g)},${Math.round(b)},0)`);
470	
471	      ctx.save();
472	      ctx.translate(px, py);
473	      ctx.scale(radiusX / maxR, radiusY / maxR);
474	      ctx.beginPath();
475	      ctx.arc(0, 0, maxR, 0, Math.PI * 2);
476	      ctx.fillStyle = gradient;
477	      ctx.fill();
478	      ctx.restore();
479	    }
480	  }
481	
482	  // Stats
483	  let totalTiles = 0, blockedTiles = 0, edgedTiles = 0;
484	  for (const key of Object.keys(matrixMap)) {
485	    totalTiles++;
486	    const t = matrixMap[key];
487	    if (!t.walkable) blockedTiles++;
488	    if (t.edges && (t.edges.northBlocked || t.edges.southBlocked || t.edges.eastBlocked || t.edges.westBlocked)) edgedTiles++;
489	  }
490	  document.getElementById('stats').innerHTML =
491	    `<span>Tiles: <b>${totalTiles}</b></span>
492	     <span>Blocked: <b>${blockedTiles}</b></span>
493	     <span>Edge-constrained: <b>${edgedTiles}</b></span>
494	     <span>Entities: <b>${entities.length}</b></span>`;
495	}
496	
497	function ingestData(data) {
498	  regionData = data;
499	  matrixMap = {};
500	  entities = [];
501	
502	  // Determine world origin
503	  const rx = data.rx ?? 0;
504	  const ry = data.ry ?? 0;
505	  worldOriginX = rx * 64;
506	  worldOriginY = ry * 64;
507	
508	  // Ingest collision matrix
509	  if (data.collision_matrix) {
510	    for (const [key, val] of Object.entries(data.collision_matrix)) {
511	      matrixMap[key] = val;
512	    }
513	  }
514	
515	  // Ingest entities
516	  if (data.entities && Array.isArray(data.entities)) {
517	    entities = data.entities;
518	  }
519	
520	  document.getElementById('status').textContent =
521	    `Region [${rx}, ${ry}] loaded. ${Object.keys(matrixMap).length} tiles, ${entities.length} entities.`;
522	
523	  redraw();
524	}
525	
526	async function loadRegion() {
527	  const rx = document.getElementById('rx').value;
528	  const ry = document.getElementById('ry').value;
529	  const filename = `ms_${rx}_${ry}.json`;
530	  document.getElementById('status').textContent = `Loading ${filename}...`;
531	
532	  try {
533	    const url = `${window.location.origin}/world/${filename}`;
534	    const resp = await fetch(url);
535	    if (!resp.ok) {
536	      document.getElementById('status').textContent = `${filename} not found in /world/ (${resp.status})`;
537	      return;
538	    }
539	    const data = await resp.json();
540	    ingestData(data);
541	  } catch (err) {
542	    document.getElementById('status').textContent = `Error: ${err.message}`;
543	  }
544	}
545	
546	// Tooltip
547	canvas.addEventListener('mousemove', (e) => {
548	  if (!regionData) return;
549	  const rect = canvas.getBoundingClientRect();
550	  const scale = parseInt(document.getElementById('scale').value);
551	  const mx = e.clientX - rect.left;
552	  const my = e.clientY - rect.top;
553	  const lx = Math.floor(mx / scale);
554	  const ly = 63 - Math.floor(my / scale);
555	
556	  if (lx < 0 || lx >= 64 || ly < 0 || ly >= 64) {
557	    tooltip.style.display = 'none';
558	    return;
559	  }
560	
561	  const wx = worldOriginX + lx;
562	  const wy = worldOriginY + ly;
563	  const key = `${wx}_${wy}`;
564	  const tile = matrixMap[key];
565	
566	  let html = `<b>[${wx}, ${wy}]</b> local [${lx}, ${ly}]<br>`;
567	
568	  if (tile) {
569	    const walkIcon = tile.walkable ? '✅' : '🚫';
570	    html += `Surface: <b>${tile.surfaceType || 'terrain'}</b> ${walkIcon}<br>`;
571	    html += `Flags: <b>0x${(tile.sourceFlags || 0).toString(16)}</b><br>`;
