576	      html += `<span class="edge-label">`;
577	      html += `N:${arrow(e.northBlocked)} S:${arrow(e.southBlocked)} `;
578	      html += `E:${arrow(e.eastBlocked)} W:${arrow(e.westBlocked)}`;
579	      html += `</span><br>`;
580	    }
581	  } else {
582	    html += '<i style="color:#555">No data</i>';
583	  }
584	
585	  // Entities at this tile
586	  const tileEnts = entities.filter(en => en.x === wx && en.y === wy);
587	  if (tileEnts.length > 0) {
588	    html += `<br><b>${tileEnts.length} entity(s):</b><br>`;
589	    for (const en of tileEnts.slice(0, 3)) {
590	      const color = en.type === 'npc' ? '#51ffff' : '#b080ff';
591	      html += `• <span style="color:${color}">${en.name || en.id}</span> (${en.type})<br>`;
592	    }
593	  }
594	
595	  tooltip.innerHTML = html;
