617	
618	// Drag and drop
619	document.body.addEventListener('dragover', e => e.preventDefault());
620	document.body.addEventListener('drop', e => {
621	  e.preventDefault();
622	  const file = e.dataTransfer.files[0];
623	  if (!file) return;
624	  const reader = new FileReader();
625	  reader.onload = () => {
