493	        const LAYOUT = ['GALESHOT', 'RICOCHET', 'PIERCING', 'SNIPE', 'CORR_SHOT', 'SNAP_SHOT', 'RAPID_FIRE', 'S_TENDRILS', 'BOMBARDMENT', 'DEATHS_SWIFT', 'DEADSHOT', 'IMBUE_SHADOW'];
494	
