583	                            <span style="position: absolute; bottom: 2px; width: 100%; font-size: 8px; color: #ccc; text-align: center; z-index: 2; line-height: 1.1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding: 0 2px;">${slotData.abilityName}</span>
584	                        `;
585	                        slot.onclick = () => executeSlotAbility(i);
586	
587	                        if (state.cooldowns[abilityId] === undefined) {
588	                            state.cooldowns[abilityId] = 0;
589	                        }
590	                    } else {
591	                        slot.classList.add('empty-slot');
592	                        slot.style.opacity = '0.2';
593	                        slot.style.background = 'rgba(255,255,255,0.03)';
594	                        slot.style.border = '1px dashed rgba(255,255,255,0.1)';
