596	                            <span style="font-size: 8px; color: #555;">Empty</span>
597	                        `;
598	                    }
599	                    actionBar.appendChild(slot);
600	                });
601	
602	                updateUI();
603	            } catch (err) {
604	                console.warn('Error loading dynamic action bar, falling back to static Ranged bar:', err);
605	                renderStaticActionBar();
606	            }
