628	            tickCounter.textContent = state.tick;
629	            const adrenPct = (state.adrenaline / 10);
630	            adrenalineFill.style.height = `${adrenPct}%`;
631	            adrenalineText.textContent = `${Math.floor(adrenPct)}%`;
632	
633	            if (activeSlots.length > 0) {
634	                activeSlots.forEach((slotData, i) => {
635	                    const slot = document.getElementById(`slot-index-${i}`);
636	                    if (!slot || !slotData.abilityId) return;
637	
638	                    const abilityId = slotData.abilityId;
639	                    const cd = state.cooldowns[abilityId] || 0;
640	
641	                    if (state.nextAbility && abilityId.toUpperCase() === state.nextAbility.toUpperCase()) {
642	                        slot.classList.add('predicted');
643	                    } else {
644	                        slot.classList.remove('predicted');
645	                    }
646	
647	                    const oldCd = slot.querySelector('.cooldown-overlay');
