658	                LAYOUT.forEach(id => {
659	                    const slot = document.getElementById(`slot-${id}`);
660	                    if (!slot) return;
661	                    const ab = ABILITIES[id];
662	                    const cd = state.cooldowns[id];
663	
664	                    if (state.nextAbility && ab.name.toUpperCase() === state.nextAbility.toUpperCase()) {
665	                        slot.classList.add('predicted');
666	                    } else {
667	                        slot.classList.remove('predicted');
668	                    }
669	
670	                    const oldCd = slot.querySelector('.cooldown-overlay');
671	                    if (oldCd) oldCd.remove();
672	
673	                    if (cd > 0) {
674	                        const overlay = document.createElement('div');
675	                        overlay.className = 'cooldown-overlay';
