427	    private commitPendingCommand(tickId: string): void {
428	        const cmd = this.pendingCommands.get(tickId);
429	        if (!cmd || cmd.state !== 'PENDING') return;
430	
431	        const kernel = EpistemicTransitionKernel.getInstance();
432	        const currentDiagnostics = kernel.getDiagnostics();
433	
434	        if (currentDiagnostics.phaseGateMultiplier < 0.3) {
435	            logger.warn({ tickId }, 'Phase gate too low — cancelling deferred commit');
436	            cmd.state = 'CANCELLED';
437	            this.pendingCommands.delete(tickId);
438	            return;
439	        }
440	
441	        cmd.state = 'COMMITTED';
442	        this.executeAction(tickId, cmd.action, cmd.predictedOutcome, cmd.transitionalVector);
443	        this.pendingCommands.delete(tickId);
444	    }
