457	            cmd.state = 'COMMITTED';
458	            this.executeAction(tickId, cmd.action, freshPrediction, cmd.transitionalVector);
459	        } else {
460	            logger.warn({ tickId }, 'Wait deadline — forced cancel');
461	            cmd.state = 'CANCELLED';
462	        }
463	
464	        this.pendingCommands.delete(tickId);
