862	    private createTickEvent(cmd: AdminCommand): TickEvent {
863	        const source = (cmd as any).source || cmd.metadata?.source || "ADMIN";
864	        // CANONICAL TIME AUTHORITY: External timestamps are forensic-only.
865	        // The simulation clock is the sole source of truth for event ordering.
866	        const timestamp = CanonicalClock.getInstance().simulatedNow();
867	        const originalTimestamp = (cmd as any).timestamp || cmd.metadata?.timestamp; // preserved for audit trail
868	        const inputs = cmd.metadata || {};
869	
870	        // Resolve coordinate if present
871	        let coord;
872	        if (cmd.type === 'teleport' || cmd.type === 'spawn') {
873	            const rawCoord = inputs.coords || (inputs.regionId ? this.grounding!.getSpatialTruth(inputs.regionId) : null);
874	            if (rawCoord) {
875	                const zVal = rawCoord.z ?? rawCoord.plane ?? 0;
876	                coord = { x: rawCoord.x, y: rawCoord.y, z: zVal, plane: zVal };
877	            }
878	        }
879	
880	        const action = cmd.type;
881	        const stableId = `ev_${this.ledger.getCurrentTick()}_${timestamp}_${CanonicalClock.getInstance().rng().range(0, 999)}`;
882	
883	        return {
884	            id: stableId,
885	            tick: this.ledger.getCurrentTick(),
886	            timestamp,
887	            action,
888	            source: source as EventSource,
889	            inputs,
890	            coord,
891	            outcome: "SUCCESS",
892	            truthClass: TruthClass.EXECUTION
893	        };
894	    }
