896	    private sortEvents(events: TickEvent[]): TickEvent[] {
897	        return [...events].sort((a, b) => {
898	            const pA = CNSGodheadPulseVolley.PRIORITY[a.source] ?? 99;
899	            const pB = CNSGodheadPulseVolley.PRIORITY[b.source] ?? 99;
900	
901	            if (pA !== pB) return pA - pB;
902	            if (a.timestamp !== b.timestamp) return a.timestamp - b.timestamp;
903	            return a.id.localeCompare(b.id);
904	        });
905	    }
