907	    private resolveConflicts(events: TickEvent[]): TickEvent[] {
908	        return events.map(event => {
909	            if (event.coord) {
910	                const tileKey = `${event.coord.x},${event.coord.y},${event.coord.plane}`;
911	                const activeLocks = this.ledger.getActiveLocks();
912	
913	                if (activeLocks.has(tileKey)) {
914	                    logger.warn({ eventId: event.id, tileKey }, '[CNS GODHEAD] REJECTED_COLLISION: Tile already locked.');
915	                    return { ...event, outcome: "REJECTED_COLLISION" as EventOutcome };
916	                }
917	
918	                this.ledger.setTileLock(tileKey, {
919	                    ownerEventId: event.id,
920	                    action: event.action
921	                });
922	            }
923	            return event;
924	        });
925	    }
