927	    /**
928	     * processQueueWithBudget - Deterministic, bounded execution of deferred operations.
929	     * Prevents async leakage and runaway tick duration.
930	     */
931	    private async processQueueWithBudget(
932	        queue: DeferredOp[],
933	        budget: QueueBudget
934	    ): Promise<QueueResult> {
935	
936	        const start = performance.now();
937	        let executed = 0;
938	        let skipped = 0;
939	
940	        const maxOps = budget.maxOps ?? Number.MAX_SAFE_INTEGER;
941	
942	        for (let i = 0; i < queue.length; i++) {
943	            const op = queue[i];
944	
945	            // hard op cap first (prevents death spirals)
946	            if (executed >= maxOps) {
947	                skipped += (queue.length - i);
948	                logger.warn({
949	                    label: budget.label,
950	                    executed,
951	                    skipped,
952	                    reason: 'MAX_OPS_REACHED'
953	                }, '[QUEUE_BUDGET] Ops cap hit, truncating execution');
954	                break;
955	            }
956	
957	            const now = performance.now();
958	            const elapsed = now - start;
959	
960	            // time budget check (core deterministic safety rail)
961	            if (elapsed >= budget.maxMs) {
962	                skipped += (queue.length - i);
963	
964	                logger.warn({
965	                    label: budget.label,
966	                    executed,
967	                    skipped,
968	                    elapsed,
969	                    maxMs: budget.maxMs,
970	                    reason: 'TIME_BUDGET_EXCEEDED'
971	                }, '[QUEUE_BUDGET] Tick budget exhausted, deferring remaining ops');
972	
973	                break;
974	            }
975	
976	            try {
977	                const result = op();
978	
979	                // allow sync or async ops without breaking tick determinism
980	                if (result instanceof Promise) {
981	                    await result;
982	                }
983	
984	                executed++;
985	            } catch (err) {
986	                skipped++;
987	
988	                logger.error({
989	                    label: budget.label,
990	                    err
991	                }, '[QUEUE_BUDGET] Deferred op failed');
992	            }
993	        }
994	
995	        const durationMs = performance.now() - start;
996	
997	        return {
998	            executed,
999	            skipped,
1000	            durationMs,
1001	            budgetExceeded: skipped > 0
1002	        };
1003	    }
